import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/error/app_exception.dart';import '../../core/widgets/states.dart';import '../providers/providers.dart';import '../widgets/content_cards.dart';
class FavoritesScreen extends ConsumerWidget{const FavoritesScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final value=ref.watch(favoritesProvider);return DefaultTabController(length:2,child:Scaffold(appBar:AppBar(title:const Text('Sevimlilar'),bottom:const TabBar(tabs:[Tab(text:'🎬 Kinolar'),Tab(text:'📺 Telekanallar')])),body:value.when(loading:()=>const AppLoading(),error:(e,_)=>AppErrorView(message:friendlyError(e),onRetry:()=>ref.invalidate(favoritesProvider)),data:(d)=>TabBarView(children:[d['movies']!.isEmpty?const _Empty('Sevimli kinolar yo‘q.'):GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:190,mainAxisExtent:330,crossAxisSpacing:12,mainAxisSpacing:14),itemCount:d['movies']!.length,itemBuilder:(_,i)=>MovieCard(movie:d['movies']![i],width:190)),d['channels']!.isEmpty?const _Empty('Sevimli telekanallar yo‘q.'):GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:210,mainAxisExtent:170,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:d['channels']!.length,itemBuilder:(_,i)=>ChannelCard(channel:d['channels']![i]))]))));}}
class _Empty extends StatelessWidget{final String text;const _Empty(this.text);@override Widget build(BuildContext context)=>Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.favorite_border,size:55,color:Colors.grey),const SizedBox(height:12),Text(text)]));}
